"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster, mq } from "./tokens.stylex";
import { rs } from "./rs";

export interface SplitProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Starting share of the first pane, in percent. */
  initial?: number;
  min?: number;
  max?: number;
  children: [React.ReactNode, React.ReactNode];
}

const styles = stylex.create({
  split: {
    display: "flex",
    flexDirection: {
      default: "row",
      [mq.phone]: "column",
    },
    width: "100%",
  },
  pane: {
    minWidth: 0,
    overflow: "hidden",
  },
  handle: {
    flexShrink: 0,
    width: {
      default: 9,
      [mq.phone]: "auto",
    },
    height: {
      default: null,
      [mq.phone]: raster.hit,
    },
    marginTop: {
      default: 0,
      [mq.phone]: -4,
    },
    marginBottom: {
      default: 0,
      [mq.phone]: -4,
    },
    marginLeft: {
      default: -4,
      [mq.phone]: 0,
    },
    marginRight: {
      default: -4,
      [mq.phone]: 0,
    },
    position: "relative",
    zIndex: 5,
    cursor: {
      default: "col-resize",
      [mq.phone]: "row-resize",
    },
    backgroundColor: "transparent",
    borderWidth: 0,
    borderStyle: "none",
    padding: 0,
    touchAction: "none",
    outline: {
      default: null,
      ":focus-visible": "none",
    },
    "::after": {
      content: '""',
      position: "absolute",
      left: {
        default: 4,
        [mq.phone]: 0,
      },
      right: {
        default: null,
        [mq.phone]: 0,
      },
      top: {
        default: 0,
        [mq.phone]: "50%",
      },
      bottom: {
        default: 0,
        [mq.phone]: "auto",
      },
      width: {
        default: 1,
        [mq.phone]: "auto",
      },
      height: {
        default: null,
        [mq.phone]: 1,
      },
      backgroundColor: raster.divider,
      transition: `background-color ${raster.durationSnap} ${raster.ease}`,
    },
    ":hover::after": {
      backgroundColor: raster.ink,
    },
    ":focus-visible::after": {
      backgroundColor: raster.ink,
    },
  },
});

/** Two panes on a draggable hairline. Arrow keys work. */
export function Split({ initial = 50, min = 20, max = 80, className, style, children, ...props }: SplitProps) {
  const [share, setShare] = React.useState(initial);
  const rootRef = React.useRef<HTMLDivElement>(null);
  const clamp = (v: number) => Math.min(max, Math.max(min, v));

  const onPointerDown = (e: React.PointerEvent<HTMLButtonElement>) => {
    e.preventDefault();
    (e.target as HTMLElement).setPointerCapture(e.pointerId);
    const rect = rootRef.current?.getBoundingClientRect();
    if (!rect) return;
    const move = (ev: PointerEvent) => setShare(clamp(((ev.clientX - rect.left) / rect.width) * 100));
    const up = () => {
      document.removeEventListener("pointermove", move);
      document.removeEventListener("pointerup", up);
    };
    document.addEventListener("pointermove", move);
    document.addEventListener("pointerup", up);
  };

  const root = rs(["rs-split", className], styles.split);
  const pane = rs(["rs-split-pane"], styles.pane);
  const handle = rs(["rs-split-handle"], styles.handle);

  return (
    <div ref={rootRef} {...props} className={root.className} style={{ ...root.style, ...style }}>
      <div className={pane.className} style={{ ...pane.style, width: `${share}%` }}>
        {children[0]}
      </div>
      <button
        type="button"
        className={handle.className}
        style={handle.style}
        role="separator"
        aria-orientation="vertical"
        aria-valuenow={Math.round(share)}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-label="Resize panes"
        onPointerDown={onPointerDown}
        onKeyDown={(e) => {
          if (e.key === "ArrowLeft") setShare((s) => clamp(s - 2));
          if (e.key === "ArrowRight") setShare((s) => clamp(s + 2));
        }}
      />
      <div className={pane.className} style={{ ...pane.style, width: `${100 - share}%` }}>
        {children[1]}
      </div>
    </div>
  );
}

import * as stylex from "@stylexjs/stylex";

/**
 * StyleX vars alias Raster CSS custom properties. Not a second scale.
 * Values live in packages/core/css/tokens.css (generated from src/tokens.ts).
 */
export const raster = stylex.defineVars({
  paper: "var(--bg)",
  ink: "var(--text)",
  gray: "var(--text-secondary)",
  accent: "var(--accent)",
  divider: "var(--divider)",
  dividerSubtle: "var(--divider-subtle)",
  tableAlt: "var(--table-alt)",
  gridLine: "var(--grid-line)",
  radiusSm: "var(--radius-sm)",
  radius: "var(--radius)",
  radiusChrome: "var(--radius-chrome)",
  radiusIn: "var(--radius-in)",
  pad: "var(--pad)",
  gutter: "var(--gutter)",
  module: "var(--grid-size)",
  gridImage: "var(--grid-image)",
  gridPos: "var(--grid-pos)",
  hit: "var(--hit)",
  controlH: "var(--control-h)",
  controlFs: "var(--control-fs)",
  controlLabel: "var(--control-label)",
  durationSnap: "var(--duration-snap)",
  duration: "var(--duration)",
  durationConfirm: "var(--duration-confirm)",
  ease: "var(--ease)",
  transition: "var(--transition)",
  textScale: "var(--text-scale)",
  hairline: "1px",
});

/** Inter stack. Same as body in base.css. Not a token var — @font-face stays CSS. */
export const rasterFont =
  "Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif";

export const rasterMono = "ui-monospace, SFMono-Regular, Menlo, monospace";

/** Compile-time media keys. StyleX only folds defineConsts, not plain strings. */
export const mq = stylex.defineConsts({
  phone: "@media (max-width: 640px)",
  mobileGrid: "@media (max-width: 480px)",
  at900: "@media (min-width: 900px)",
  at899: "@media (max-width: 899px)",
  rail: "@media (min-width: 1024px)",
  wide: "@media (min-width: 1440px)",
  reduce: "@media (prefers-reduced-motion: reduce)",
  touch: "@media (hover: none)",
});

/** Phone recut (≤640). Desktop stays the poster. */
export const phone = mq.phone;

/** Mobile grid (≤480). */
export const mobileGrid = mq.mobileGrid;

/** Catalog rail. */
export const rail = mq.rail;

/** Wide catalog. */
export const wide = mq.wide;

import type { CSSProperties } from "react";
import * as stylex from "@stylexjs/stylex";
import type { CompiledStyles, InlineStyles } from "@stylexjs/stylex";
import { cx } from "./cx";

type Nested<T> = T | ReadonlyArray<Nested<T>>;

/** Exactly what stylex.props accepts: compiled leaves, falsy, nested arrays, or a leaf with inline styles. */
export type Leaves = ReadonlyArray<Nested<null | undefined | CompiledStyles | boolean | Readonly<[CompiledStyles, InlineStyles]>>>;

type StyleXProps = { className?: string; style?: CSSProperties };

/**
 * The one seam every component styles through: semantic rs-* class names
 * (the CSS-first contract, and what packages/core generates CSS for) merged
 * with the compiled StyleX leaves that paint the React tree.
 */
export function rs(classNames: Array<string | false | null | undefined>, ...styles: Leaves): StyleXProps {
  const sx = stylex.props(...styles) as StyleXProps;
  return {
    className: cx(...classNames, sx.className),
    style: sx.style,
  };
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}
